// Final Output v7: uses $input as primary source of truth
// Three paths arrive here:
//   1. Normal + Telegram sent: Merge Telegram Result → here
//   2. Normal + test_mode (no Telegram): IF Send Telegram (false) → here
//   3. None path: IF Skip Outbound (false) → here

const current = $input.first().json;
const decision = current.decision || {};
const intent = decision.intent;
const branch = current._branch || null;

const branchMap = {
  create_task: 'Create Task',
  update_task: 'Update Task (Placeholder)',
  complete_task: 'Complete Task (Placeholder)',
  cancel_task: 'Cancel Task (Placeholder)',
  list_tasks: 'Format Task List',
  create_reminder: 'Create Reminder',
  update_reminder: 'Update Reminder (Placeholder)',
  cancel_reminder: 'Cancel Reminder (Placeholder)',
  list_reminders: 'Format Reminder List',
  search_memory: 'Search Memory (Placeholder)',
  general_response: 'General Response',
  clarify: 'Clarify',
  save_improvement_request: 'Save Improvement Request',
  none: 'None (No Action)'
};

const actualBranch = branch || branchMap[intent] || 'unknown';
const isFallback = (branch === 'fallback_to_clarify');
const outboundSkipped = (intent === 'none');

// Inbound message ID
let inboundId = null;
try { inboundId = $('Insert Inbound Message').first().json.id || null; } catch(e) { inboundId = '_error_reading_inbound'; }

// Outbound message ID (from Merge Outbound Result on normal path)
const outboundId = current._outbound_message_id || null;

// Response from current item (already normalized by Normalize Client Response)
const finalResponse = decision.response || '';

// Normalization metadata
const responseNormalized = current._response_normalized === true;
const memoryAckAppended = current._memory_ack_appended === true;

// Telegram send result
const telegramResult = current._telegram_result || null;
const telegramSent = telegramResult ? telegramResult.sent === true : false;
const telegramMessageIdSent = (telegramResult && telegramResult.message_id) || null;

// Aligned skip_reason values (short form used everywhere)
let telegramSkipReason = null;
if (outboundSkipped) {
  telegramSkipReason = 'intent_none';
} else if (current.test_mode === true) {
  telegramSkipReason = 'test_mode';
} else if (telegramResult && !telegramResult.sent) {
  telegramSkipReason = telegramResult.reason || 'send_failed';
}

// Branch-specific result data
let branchResult = {};

if (intent === 'create_task') {
  try {
    const r = $('Create Task').first().json;
    branchResult = { task_created: !!(r && r.id), task_id: r ? r.id : null };
  } catch(e) { branchResult = { task_created: false, _error: 'create_task_node_read_failed' }; }
} else if (intent === 'create_reminder') {
  try {
    const r = $('Create Reminder').first().json;
    branchResult = { reminder_created: !!(r && r.id), reminder_id: r ? r.id : null };
  } catch(e) { branchResult = { reminder_created: false, _error: 'create_reminder_node_read_failed' }; }
} else if (intent === 'save_improvement_request') {
  try {
    const r = $('Save Improvement Request').first().json;
    branchResult = { improvement_saved: !!(r && r.id), improvement_id: r ? r.id : null };
  } catch(e) { branchResult = { improvement_saved: false, _error: 'save_improvement_node_read_failed' }; }
} else if (branch === 'list_tasks') {
  branchResult = { tasks_listed: true, task_rows: current._listed_task_rows || [] };
} else if (branch === 'list_reminders') {
  branchResult = { reminders_listed: true, reminder_rows: current._listed_reminder_rows || [] };
} else if (intent === 'none') {
  branchResult = { action: 'none', outbound_skipped: true };
}

// Build routing object
const routing = {
  actual_branch: actualBranch,
  is_fallback: isFallback,
  outbound_skipped: outboundSkipped,
  outbound_reason: outboundSkipped ? 'intent_none' : 'normal'
};

if (isFallback && current._original_unknown_intent) {
  routing.original_unknown_intent = current._original_unknown_intent;
}

return [{
  json: {
    ok: true,
    workflow: 'brain_main_inbound_mvp',
    contract_version: decision.version || 'brain-decision-v1',
    resolved: {
      organization_id: current.organization_id,
      tenant_id: current.tenant_id,
      business_id: (current.context && current.context.business) ? current.context.business.id : null
    },
    decision: {
      intent: intent,
      domain: decision.domain,
      debug_summary: decision.debug_summary,
      requires_confirmation: decision.requires_confirmation,
      requires_clarification: decision.requires_clarification
    },
    routing: routing,
    writes: {
      message_inbound_id: inboundId,
      message_outbound_id: outboundId,
      ...branchResult
    },
    telegram: {
      sent: telegramSent,
      chat_id: current.telegram_chat_id || null,
      message_id_sent: telegramMessageIdSent,
      skip_reason: telegramSkipReason
    },
    response: finalResponse,
    response_normalized: responseNormalized,
    memory_ack_appended: memoryAckAppended,
    memory_writes: decision.memory_writes || []
  }
}];

const ctx = $('Parse and Validate Brain Contract').first().json;
