}));

function fmtDate(d) {
  if (!d) return null;
  const dt = new Date(d);
  if (isNaN(dt)) return d;
  return dt.toLocaleDateString('ro-RO', { day: '2-digit', month: '2-digit', year: 'numeric' });
}

let responseText = '';
if (formatted.length === 0) {
  responseText = 'Nu ai task-uri.';
} else {
  responseText = formatted.map((t, i) => {
    let line = (i + 1) + '. ' + t.title;
    if (t.priority !== 'normal') line += ' [' + t.priority + ']';
    const dateStr = fmtDate(t.due_date) || fmtDate(t.due_at);
    if (dateStr) line += ' — ' + dateStr;
    return line;
  }).join('\n');
}

const updatedDecision = Object.assign({}, ctx.decision, { response: responseText });

return [{
  json: {
    ...ctx,
    decision: updatedDecision,
    _branch: 'list_tasks',
