// Normalize Client Response (v7): deterministic user-facing messages
// Placed AFTER Privacy Gate Outbound, BEFORE IF Skip Outbound.
// Overwrites decision.response with standardized text for key intents.
// Memory acknowledgment appended deterministically when appropriate.

const item = $input.first().json;
const decision = item.decision || {};
const intent = decision.intent;
const branch = item._branch || null;

function formatDateRO(value) {
  if (!value) return '';

  const raw = String(value).trim();
  const dateOnly = /^\d{4}-\d{2}-\d{2}$/;

  if (dateOnly.test(raw)) {
    const [year, month, day] = raw.split('-');
    return `${day}/${month}/${year}`;
  }

  const d = new Date(raw);
  if (isNaN(d.getTime())) return raw;

  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  const hasTime = /T\d{2}:\d{2}/.test(raw);

  if (!hasTime) {
    return `${day}/${month}/${year}`;
  }

  const hours = String(d.getHours()).padStart(2, '0');
  const minutes = String(d.getMinutes()).padStart(2, '0');

  return `${day}/${month}/${year} ${hours}:${minutes}`;
}

let finalResponse = decision.response || '';
let responseNormalized = false;
let memoryAckAppended = false;

// === RESPONSE NORMALIZATION RULES ===

if (branch === 'list_tasks') {
  // Keep formatter-generated response (built from real DB rows)
  // Do NOT overwrite with generic LLM wording
  finalResponse = decision.response || '';

} else if (branch === 'list_reminders') {
  // Keep formatter-generated response (built from real DB rows)
  finalResponse = decision.response || '';

} else if (intent === 'create_task') {
  // Standardized task creation confirmation
  const ta = decision.task_action || {};
  let msg = 'Am creat task-ul: ' + (ta.title || 'fara titlu') + '.';
  if (ta.due_date) {
    msg += ' Scadent: ' + formatDateRO(ta.due_date) + '.';
  } else if (ta.due_at) {
    msg += ' Scadent: ' + formatDateRO(ta.due_at) + '.';
  }
  if (ta.priority && ta.priority !== 'normal') {
    msg += ' Prioritate: ' + ta.priority + '.';
  }
  finalResponse = msg;
  responseNormalized = true;

} else if (intent === 'create_reminder') {
  // Standardized reminder creation confirmation
  const ra = decision.reminder_action || {};
  let msg = 'Am setat reminderul: ' + (ra.title || 'fara titlu') + '.';
  if (ra.remind_at) {
    msg += ' Te voi notifica la: ' + formatDateRO(ra.remind_at) + '.';
  }
  finalResponse = msg;
  responseNormalized = true;

} else if (intent === 'clarify' || branch === 'fallback_to_clarify') {
  // Standardized clarification message
  finalResponse = 'Nu am inteles exact ce doresti. Poti reformula?';
  responseNormalized = true;

} else if (intent === 'save_improvement_request') {
  // Standardized improvement acknowledgment
  finalResponse = 'Am notat sugestia ta de imbunatatire.';
  responseNormalized = true;

} else if (intent === 'none') {
  // No response — keep empty (outbound skipped entirely)
  finalResponse = '';

} else if (intent === 'general_response') {
  // Keep LLM response as-is
  finalResponse = decision.response || '';

} else {
  // Placeholder intents and unknown: keep LLM response
  finalResponse = decision.response || '';
}

// === MEMORY ACKNOWLEDGMENT (deterministic) ===
// Append ONLY for user-facing intents where it makes sense
// NEVER for list_tasks, list_reminders, none, clarify, fallback_to_clarify

const memoryWrites = decision.memory_writes || [];
const memoryAckAllowed = ['general_response', 'create_task', 'create_reminder', 'save_improvement_request'];
const isNotClarifyBranch = (branch !== 'fallback_to_clarify');

if (memoryWrites.length > 0 && memoryAckAllowed.includes(intent) && isNotClarifyBranch && intent !== 'none') {
  finalResponse += '\n\nAm retinut si informatia pentru contextul viitor.';
  memoryAckAppended = true;
}

// === OUTPUT ===
// Overwrite decision.response with normalized version
// Add metadata flags for Final Output to report

const updatedDecision = Object.assign({}, decision, { response: finalResponse });

return [{
  json: Object.assign({}, item, {
    decision: updatedDecision,
    _response_normalized: responseNormalized,
    _memory_ack_appended: memoryAckAppended
  })
}];

