// Prepare Embedding Batch: extracts memory_writes and builds OpenAI request
const item = $input.first().json;
const decision = item.decision || {};
const memoryWrites = decision.memory_writes || [];

if (memoryWrites.length === 0) {
  // Safety: should not reach here (IF gate filters), but handle gracefully
  return [{ json: { ...item, _memory_skipped: true } }];
}

// Extract content strings for batch embedding
const contents = memoryWrites.map(m => m.content);

return [{
  json: {
    _original_context: item,
    _memory_writes: memoryWrites,
    _embedding_input: contents,
    _tenant_id: item.tenant_id,
    _raw_user_message: item.raw_user_message
  }
}];

// Build Memory Insert Items: maps embeddings to individual insert-ready items
const prev = $('Prepare Embedding Batch').first().json;
const apiResponse = $input.first().json;
const memoryWrites = prev._memory_writes || [];
const tenantId = prev._tenant_id;

// Handle OpenAI API errors gracefully
if (!apiResponse.data || !Array.isArray(apiResponse.data)) {
  // API failed — restore context and skip memory writes
  const ctx = prev._original_context;
  return [{
    json: {
      ...ctx,
      _memory_write_status: 'embedding_api_failed',
      _memory_write_error: apiResponse.error || 'unknown',
      _memory_write_count: 0
    }
  }];
}

const embeddings = apiResponse.data;

// Create one output item per memory_write with its embedding
const items = memoryWrites.map((mw, idx) => {
  const emb = embeddings[idx];
  if (!emb || !emb.embedding) return null;

  // Format embedding as pgvector string: [0.1,0.2,...]
  const embStr = '[' + emb.embedding.join(',') + ']';

  return {
    json: {
      tenant_id: tenantId,
      content: mw.content,
      embedding_str: embStr,
      memory_category: mw.category,
      memory_kind: mw.type || 'fact',
      durability: 'stable',
      raw_user_message: (prev._raw_user_message || '').substring(0, 200),
      _original_context: prev._original_context,
      _total_memories: memoryWrites.length,
      _memory_index: idx
    }
  };
}).filter(x => x !== null);

if (items.length === 0) {
  const ctx = prev._original_context;
  return [{
    json: {
      ...ctx,
      _memory_write_status: 'no_valid_embeddings',
      _memory_write_count: 0
    }
  }];
}

return items;

// Restore Context After Memory Write
// Gets original context and adds memory write metadata
const allItems = $input.all();
const firstItem = allItems[0].json;

// Check if we have the original context (from Build Memory Insert Items)
let ctx;
if (firstItem._original_context) {
  ctx = firstItem._original_context;
} else if (firstItem._memory_write_status) {
  // Error path — context was already restored in Build node
  return [{ json: firstItem }];
} else {
  // Fallback: try to get from IF node
  ctx = $('IF Has Memory Writes').first().json;
}

// Count successful inserts/dedup
let insertedCount = 0;
let dedupCount = 0;
for (const item of allItems) {
  const action = item.json.action || '';
  if (action === 'inserted') insertedCount++;
  else if (action === 'deduplicated') dedupCount++;
}

return [{
  json: {
    ...ctx,
    _memory_write_status: 'completed',
    _memory_write_count: insertedCount + dedupCount,
    _memory_inserted: insertedCount,
    _memory_deduplicated: dedupCount
  }
}];
